export const deleteUnusedTags = async (
  workspaceId: string
): Promise<Result<{ deletedCount: number }, { code: TagError; message: string }>> => {
  validateInputs([workspaceId, ZId]);

  try {
    // Find tags that have no responses attached to them
    const unusedTagIds = await prisma.tagsOnResponses.findMany({
      where: {
        response: {
          survey: { workspaceId },
        },
      },
      distinct: [\"tagId\"],
      select: { tagId: true },
