import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { problemInternalError } from "@/app/api/v3/lib/response";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { deleteUnusedTags } from "@/modules/workspaces/settings/lib/tag";
import { ZBulkDeleteUnusedTagsQuery } from "../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  schemas: { query: ZBulkDeleteUnusedTagsQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    const access = await requireV3WorkspaceAccess(
      authentication,
      parsedInput.query.workspaceId,
      "readWrite",
      requestId,
      instance
    );
    if (access instanceof Response) return access;

    const result = await deleteUnusedTags(access.workspaceId);
    if (!result.ok) {
      return problemInternalError(requestId, "Unable to delete unused tags", instance);
    }

    return new Response(
      JSON.stringify({
        data: { deletedCount: result.data.deletedCount },
      }),
      {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }
    );
  },
});

