"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { tagKeys } from "../lib/query";

interface DeleteUnusedTagsResult {
  deletedCount: number;
}

/** Delete all unused tags for a workspace, then invalidate the list. */
export const useDeleteUnusedTags = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation<DeleteUnusedTagsResult, Error, void>({
    mutationFn: async () => {
      const response = await fetch(
        `/api/v3/tags/bulk-delete-unused?workspaceId=${encodeURIComponent(workspaceId)}`,
        { method: "POST" }
      );
      if (!response.ok) {
        throw new Error("Failed to delete unused tags");
      }
      const { data } = (await response.json()) as { data: DeleteUnusedTagsResult };
      return data;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

