  workspaceId: string
): Promise<Result<{ deletedCount: number }, { code: TagError; message: string }>> => {
  validateInputs([workspaceId, ZId]);

  try {
    // Find tags that have no responses attached to them
    const unusedTagIds = await prisma.tagsOnResponses.findMany({
      where: {
        response: {
          survey: { workspaceId },
        },
      },
      distinct: ["tagId"],
      select: { tagId: true },
    });

    const usedTagIds = new Set(unusedTagIds.map((r) => r.tagId));

    const unusedTags = await prisma.tag.deleteMany({
      where: {
        workspaceId,
        id: { notIn: [...usedTagIds] },
      },
    });

    return ok({ deletedCount: unusedTags.count });
  } catch (error) {
    if (isPrismaKnownRequestError(error, PrismaErrorType.RecordNotFound)) {
      return err({
        code: TagError.TAG_NOT_FOUND,
        message: "Tag not found",
      });
    }

    return err({
      code: TagError.UNEXPECTED_ERROR,
      message: error instanceof Error ? error.message : "Unknown error occurred",
    });
  }
};

